        # String validations
        if isinstance(value, str):
            min_len = rules.get("min_length")
            if min_len is not None and len(value) < min_len:
                errors.append(
                    f"Field '{field_name}' must be at least {min_len} characters"
                )

            max_len = rules.get("max_length")
            if max_len is not None and len(value) > max_len:
                errors.append(
                    f"Field '{field_name}' must be at most {max_len} characters"
                )

            pattern = rules.get("pattern")
            if pattern and not re.match(pattern, value):
                errors.append(f"Field '{field_name}' does not match pattern {pattern}")

        # Numeric validations
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            min_val = rules.get("min_value")
            if min_val is not None and value < min_val:
                errors.append(f"Field '{field_name}' must be >= {min_val}")

            max_val = rules.get("max_value")
            if max_val is not None and value > max_val:
                errors.append(f"Field '{field_name}' must be <= {max_val}")

